  1: import promptAction from '@ohos.promptAction';
  2: import { DesignTokens } from '../../model/DesignTokens';
  3: import { ColorsInterface } from '../../model/TokenInterfaces';
  4: import { ThemeManager } from '../../manager/ThemeManager';
  5: import { WebDavSyncManager, WebDavSettings, WebDavSyncResult, WebDavBackupPlainResult } from '../../sync/WebDavSyncManager';
  6: import { DataSyncManager } from '../../sync/DataSyncManager';
  7: import { WebDavStateStore } from '../../utils/WebDavStateStore';
  8: import { SelectOption } from './SettingsCommon';
  9: 
 10: interface DialogIndexResult {
 11:   index: number;
 12: }
 13: 
 14: const WEBDAV_AUTOSYNC_INTERVAL_HOURS: number[] = [1, 3, 6, 12, 24];
 15: const WEBDAV_AUTOSYNC_INTERVAL_OPTIONS: SelectOption[] = [
 16:   { value: '每1小时' },
 17:   { value: '每3小时' },
 18:   { value: '每6小时（默认）' },
 19:   { value: '每12小时' },
 20:   { value: '每24小时' }
 21: ];
 22: 
 23: @Component
 24: export struct SettingsSyncSection {
 25:   @Link webdavEndpoint: string;
 26:   @Link webdavUsername: string;
 27:   @Link webdavPassword: string;
 28:   @Link webdavSyncPassword: string;
 29:   @Link webdavRemoteRoot: string;
 30:   @Link showWebdavPassword: boolean;
 31:   @Link showWebdavSyncPassword: boolean;
 32:   @Link webdavAutoSyncEnabled: boolean;
 33:   @Link webdavAutoSyncIntervalIndex: number;
 34:   @Link webdavAutoSyncUploadModelEnabled: boolean;
 35:   @Link webdavAutoSyncUploadBackupEnabled: boolean;
 36:   @Link webdavAutoSyncLastSuccessMs: number;
 37:   @Link webdavAutoSyncLastError: string;
 38:   @StorageProp('ThemeRefreshToken') @Watch('onThemeChange') themeRefreshToken: number = 0;
 39:   @State private colors: ColorsInterface = ThemeManager.getInstance().getColors();
 40: 
 41:   @State webdavResult: string = '';
 42:   @State webdavBackupResult: string = '';
 43:   @State webdavBusy: boolean = false;
 44:   @State restoreDialogShowing: boolean = false; // Bug fix: 防止重复弹出恢复确认对话框
 45: 
 46:   private webdavManager: WebDavSyncManager = WebDavSyncManager.getInstance();
 47:   private webdavStateStore: WebDavStateStore = WebDavStateStore.getInstance();
 48:   private syncManager: DataSyncManager = DataSyncManager.getInstance();
 49: 
 50:   private onThemeChange(): void {
 51:     this.colors = ThemeManager.getInstance().getColors();
 52:   }
 53: 
 54:   aboutToAppear(): void {
 55:     void this.loadAutoSyncSettings();
 56:   }
 57: 
 58:   private async loadAutoSyncSettings(): Promise<void> {
 59:     try {
 60:       const enabled = await this.webdavStateStore.getAutoSyncEnabled();
 61:       const hours = await this.webdavStateStore.getAutoSyncIntervalHours();
 62:       const uploadModel = await this.webdavStateStore.getAutoSyncUploadModelEnabled();
 63:       const uploadBackup = await this.webdavStateStore.getAutoSyncUploadBackupEnabled();
 64:       const lastSuccess = await this.webdavStateStore.getAutoSyncLastSuccessMs();
 65:       const lastError = await this.webdavStateStore.getAutoSyncLastError();
 66: 
 67:       this.webdavAutoSyncEnabled = enabled;
 68:       this.webdavAutoSyncUploadModelEnabled = uploadModel;
 69:       this.webdavAutoSyncUploadBackupEnabled = uploadBackup;
 70:       this.webdavAutoSyncLastSuccessMs = lastSuccess;
 71:       this.webdavAutoSyncLastError = lastError;
 72: 
 73:       const index = WEBDAV_AUTOSYNC_INTERVAL_HOURS.indexOf(hours);
 74:       this.webdavAutoSyncIntervalIndex = index >= 0 ? index : 2;
 75:     } catch (e) {
 76:       console.error('[SettingsSyncSection] Failed to load auto sync settings:', e);
 77:     }
 78:   }
 79: 
 80:   private async saveWebDavAutoSyncSettings(): Promise<void> {
 81:     await this.webdavStateStore.setAutoSyncEnabled(this.webdavAutoSyncEnabled);
 82:     const hours = WEBDAV_AUTOSYNC_INTERVAL_HOURS[this.webdavAutoSyncIntervalIndex] ?? 6;
 83:     await this.webdavStateStore.setAutoSyncIntervalHours(hours);
 84:     await this.webdavStateStore.setAutoSyncUploadModelEnabled(this.webdavAutoSyncUploadModelEnabled);
 85:     await this.webdavStateStore.setAutoSyncUploadBackupEnabled(this.webdavAutoSyncUploadBackupEnabled);
 86:   }
 87: 
 88:   private formatWebDavAutoSyncLastSuccess(): string {
 89:     const ms = this.webdavAutoSyncLastSuccessMs;
 90:     if (ms <= 0) {
 91:       return '从未';
 92:     }
 93:     try {
 94:       return new Date(ms).toLocaleString();
 95:     } catch {
 96:       return String(ms);
 97:     }
 98:   }
 99: 
100:   private async saveWebDavSettings(): Promise<boolean> {
101:     const s = new WebDavSettings(
102:       this.webdavEndpoint.trim(),
103:       this.webdavUsername.trim(),
104:       this.webdavPassword,
105:       this.webdavSyncPassword,
106:       this.webdavRemoteRoot.trim().length > 0 ? this.webdavRemoteRoot.trim() : '/weiyu_sync',
107:       true
108:     );
109:     const saved = await this.webdavManager.setSettings(s);
110:     this.webdavResult = saved ? '✅ WebDAV 设置已保存' : '⚠️ WebDAV 设置保存失败';
111:     return saved;
112:   }
113: 
114:   private readonly OPERATION_TIMEOUT = 120000; // 120秒超时
115: 
116:   private async runWithTimeout<T>(operation: () => Promise<T>, timeoutMs: number): Promise<T> {
117:     return Promise.race([
118:       operation(),
119:       new Promise<T>((_, reject) => {
120:         setTimeout(() => reject(new Error('操作超时，请检查网络连接')), timeoutMs);
121:       })
122:     ]);
123:   }
124: 
125:   private async runWebDavAction(fn: () => Promise<WebDavSyncResult>): Promise<void> {
126:     if (this.webdavBusy) return;
127:     this.webdavBusy = true;
128:     try {
129:       const res = await this.runWithTimeout(fn, this.OPERATION_TIMEOUT);
130:       this.webdavResult = res.success ? `✅ ${res.message}` : `⚠️ ${res.message}：${res.detail}`;
131:       promptAction.showToast({ message: res.message, duration: 1200 });
132:     } catch (e) {
133:       const msg = e instanceof Error ? e.message : String(e);
134:       this.webdavResult = `⚠️ WebDAV 操作异常：${msg}`;
135:       promptAction.showToast({ message: 'WebDAV 操作异常', duration: 1200 });
136:     } finally {
137:       this.webdavBusy = false;
138:     }
139:   }
140: 
141:   private async runWebDavBackupAction(fn: () => Promise<WebDavSyncResult>, loadingMessage: string = '正在处理...'): Promise<void> {
142:     if (this.webdavBusy) return;
143:     this.webdavBusy = true;
144:     this.webdavBackupResult = loadingMessage;
145: 
146:     await new Promise<void>((resolve) => setTimeout(resolve, 50));
147: 
148:     try {
149:       const res = await this.runWithTimeout(fn, this.OPERATION_TIMEOUT);
150:       this.webdavBackupResult = res.success ? `✅ ${res.message}` : `⚠️ ${res.message}：${res.detail}`;
151:       promptAction.showToast({ message: res.message, duration: 1200 });
152:     } catch (e) {
153:       const msg = e instanceof Error ? e.message : String(e);
154:       this.webdavBackupResult = `⚠️ WebDAV 操作异常：${msg}`;
155:       promptAction.showToast({ message: 'WebDAV 操作异常', duration: 1200 });
156:     } finally {
157:       this.webdavBusy = false;
158:     }
159:   }
160: 
161:   private async webdavBackup(): Promise<void> {
162:     await this.runWebDavBackupAction(async () => this.webdavManager.backupToCloudInBackground(), '正在备份到云端...');
163:   }
164: 
165:   private async webdavRestore(): Promise<void> {
166:     // Bug fix: 检查是否已经在处理中，防止重复触发
167:     if (this.webdavBusy) {
168:       return;
169:     }
170: 
171:     // Bug fix: 防止重复弹出恢复确认对话框
172:     if (this.restoreDialogShowing) {
173:       console.warn('[SettingsSyncSection] Restore dialog already showing, skipping duplicate call');
174:       return;
175:     }
176: 
177:     // 第一层确认：点击按钮后立即弹出，防止误触
178:     try {
179:       const firstConfirm = await promptAction.showDialog({
180:         title: '从云端恢复',
181:         message: '⚠️ 警告：此操作将从云端下载备份并覆盖本地数据，本地未同步的学习记录将丢失。\n\n确定要继续吗？',
182:         buttons: [
183:           { text: '取消', color: String(this.colors.TEXT_SECONDARY) },
184:           { text: '继续', color: String(this.colors.WARNING) }
185:         ]
186:       });
187:       const clicked = firstConfirm as DialogIndexResult;
188:       if (clicked.index === 0) {
189:         return; // 用户取消，不执行任何操作
190:       }
191:     } catch (e) {
192:       return; // 对话框被关闭，视为取消
193:     }
194: 
195:     // 开始下载和解析流程，手动管理状态
196:     this.webdavBusy = true;
197:     this.restoreDialogShowing = true;
198:     this.webdavBackupResult = '正在下载云端备份...';
199:     
200:     // Yield to UI thread to show download message
201:     await new Promise<void>((resolve) => setTimeout(resolve, 0));
202: 
203:     let download: WebDavBackupPlainResult | null = null;
204:     
205:     try {
206:       // Step 1: Download backup from cloud
207:       download = await this.runWithTimeout(() => this.webdavManager.downloadBackupPlain(false), this.OPERATION_TIMEOUT);
208:       
209:       if (!download.result.success) {
210:         this.webdavBackupResult = `⚠️ ${download.result.message}：${download.result.detail}`;
211:         promptAction.showToast({ message: download.result.message, duration: 1200 });
212:         this.webdavBusy = false;
213:         this.restoreDialogShowing = false;
214:         return;
215:       }
216:       
217:       if (download.plain.length === 0) {
218:         this.webdavBackupResult = '⚠️ 云端无备份：未找到可用的备份文件';
219:         promptAction.showToast({ message: '云端无备份', duration: 1200 });
220:         this.webdavBusy = false;
221:         this.restoreDialogShowing = false;
222:         return;
223:       }
224: 
225:       // Step 2: Parse and preview backup data
226:       this.webdavBackupResult = '正在解析备份数据...';
227:       await new Promise<void>((resolve) => setTimeout(resolve, 0));
228:       
229:       const preview = await this.syncManager.previewImport(download.plain);
230:       if (preview.errors.length > 0) {
231:         this.webdavBackupResult = `⚠️ 预览失败：${preview.errors.join('; ')}`;
232:         promptAction.showToast({ message: '预览失败', duration: 1200 });
233:         this.webdavBusy = false;
234:         this.restoreDialogShowing = false;
235:         return;
236:       }
237: 
238:       // Release busy state while waiting for user confirmation
239:       this.webdavBusy = false;
240:       this.webdavBackupResult = ''; // Clear loading message before showing dialog
241: 
242:       // Step 3: Show second confirmation dialog with preview data
243:       const sample = preview.sampleUpdatedWords.length > 0 ? `\n示例：${preview.sampleUpdatedWords.join('、')}` : '';
244:       const msg = `⚠️ 警告：此操作将覆盖本地数据！\n\n将覆盖更新 ${preview.updated} 词，新增 ${preview.imported} 词，共 ${preview.total} 词。${sample}\n\n本地未同步的学习记录将丢失，请确认是否继续？`;
245: 
246:       let userConfirmed = false;
247:       try {
248:         const dialogResult = await promptAction.showDialog({
249:           title: '⚠️ 恢复确认',
250:           message: msg,
251:           buttons: [
252:             { text: '取消', color: String(this.colors.TEXT_SECONDARY) },
253:             { text: '确认恢复', color: String(this.colors.ERROR) }
254:           ]
255:         });
256: 
257:         const clickedSecond = dialogResult as DialogIndexResult;
258:         userConfirmed = clickedSecond.index === 1;
259:       } catch (e) {
260:         userConfirmed = false;
261:       }
262: 
263:       if (!userConfirmed) {
264:         this.webdavBackupResult = '✅ 已取消恢复';
265:         promptAction.showToast({ message: '已取消恢复', duration: 1200 });
266:         this.restoreDialogShowing = false;
267:         return;
268:       }
269: 
270:       // Step 4: User confirmed, proceed with restore
271:       this.webdavBusy = true;
272:       this.webdavBackupResult = '正在恢复数据...';
273:       await new Promise<void>((resolve) => setTimeout(resolve, 0));
274: 
275:       const importResult = await this.runWithTimeout(() => this.webdavManager.importPlainBackup(download!.plain), this.OPERATION_TIMEOUT);
276:       this.webdavBackupResult = importResult.success ? `✅ ${importResult.message}` : `⚠️ ${importResult.message}：${importResult.detail}`;
277:       promptAction.showToast({ message: importResult.message, duration: 1200 });
278: 
279:     } catch (e) {
280:       const msg = e instanceof Error ? e.message : String(e);
281:       this.webdavBackupResult = `⚠️ WebDAV 操作异常：${msg}`;
282:       promptAction.showToast({ message: 'WebDAV 操作异常', duration: 1200 });
283:     } finally {
284:       this.webdavBusy = false;
285:       this.restoreDialogShowing = false;
286:     }
287:   }
288: 
289:   private async webdavSyncNow(): Promise<void> {
290:     if (this.webdavBusy) return;
291:     this.webdavBusy = true;
292:     this.webdavResult = '正在同步数据...';
293: 
294:     // 使用更长的延迟确保 UI 更新
295:     await new Promise<void>((resolve) => setTimeout(resolve, 100));
296: 
297:     try {
298:       const saved = await this.saveWebDavSettings();
299:       if (!saved) {
300:         this.webdavResult = '⚠️ 保存设置失败，请先保存 WebDAV 设置';
301:         promptAction.showToast({ message: '保存设置失败', duration: 1200 });
302:         return;
303:       }
304: 
305:       // 给 UI 线程时间响应
306:       await new Promise<void>((resolve) => setTimeout(resolve, 50));
307: 
308:       const res = await this.runWithTimeout(() => this.webdavManager.syncIncremental(), this.OPERATION_TIMEOUT);
309:       this.webdavResult = res.success ? `✅ ${res.message}` : `⚠️ ${res.message}：${res.detail}`;
310:       promptAction.showToast({ message: res.message, duration: 1200 });
311:     } catch (e) {
312:       const msg = e instanceof Error ? e.message : String(e);
313:       this.webdavResult = `⚠️ WebDAV 操作异常：${msg}`;
314:       promptAction.showToast({ message: 'WebDAV 操作异常', duration: 1200 });
315:     } finally {
316:       this.webdavBusy = false;
317:     }
318:   }
319: 
320:   private async webdavTest(): Promise<void> {
321:     await this.runWebDavAction(async () => {
322:       const settings = new WebDavSettings(
323:         this.webdavEndpoint.trim(),
324:         this.webdavUsername.trim(),
325:         this.webdavPassword,
326:         this.webdavSyncPassword,
327:         this.webdavRemoteRoot.trim().length > 0 ? this.webdavRemoteRoot.trim() : '/weiyu_sync',
328:         true
329:       );
330:       const missing = this.validateSettings(settings);
331:       if (missing.length > 0) {
332:         return WebDavSyncResult.fail('配置不完整', missing);
333:       }
334:       this.webdavManager.setSettings(settings);
335:       return this.webdavManager.testConnection();
336:     });
337:   }
338: 
339:   private validateSettings(settings: WebDavSettings): string {
340:     if (settings.endpoint.length === 0) return 'WebDAV 地址不能为空';
341:     if (settings.username.length === 0) return '账号不能为空';
342:     if (settings.password.length === 0) return '密码不能为空';
343:     if (settings.syncPassword.length < 4) return '同步密码至少需要4位';
344:     return '';
345:   }
