429:   @Builder
430:   private buildBasicConfigCard() {
431:     Column() {
432:       Text('基础配置')
433:         .fontSize(DesignTokens.Typography.FONT_SIZE_BASE)
434:         .fontWeight(DesignTokens.Typography.FONT_WEIGHT_MEDIUM)
435:         .fontColor(this.colors.TEXT_PRIMARY)
