456:   @Builder
457:   private buildAutoSyncCard() {
458:     Column() {
459:       Text('自动同步')
460:         .fontSize(DesignTokens.Typography.FONT_SIZE_BASE)
461:         .fontWeight(DesignTokens.Typography.FONT_WEIGHT_MEDIUM)
462:         .fontColor(this.colors.TEXT_PRIMARY)
